// Writes docs/TEMPLATE_WORDING.md: a plain reading copy of every template, for wording review (D-010).
import { writeFileSync } from 'node:fs';
import { TEMPLATES, CATALOGUE_PROBLEMS } from '../src/content/templates/index.js';
import { summariseTemplate } from '../src/domain/templates.js';
import { CONSENT_NOTICE } from '../src/content/notices.js';

if (CATALOGUE_PROBLEMS.length > 0) {
  process.stderr.write(`Template problems:\n- ${CATALOGUE_PROBLEMS.join('\n- ')}\n`);
  process.exit(1);
}

const out = [
  '# Template wording',
  '',
  'Generated by `npm run templates:wording`. Do not edit this file: edit the templates in `src/content/templates/` and run the script again.',
  '',
  `Every template carries this statement: ${CONSENT_NOTICE}`,
  '',
];

for (const t of TEMPLATES) {
  const s = summariseTemplate(t);
  out.push(`## ${t.title}`, '', t.summary, '');
  out.push(`Id \`${t.templateId}\`, version ${t.version}. ${s.categories} categories, ${s.items} items. ${t.defaultVisibility === 'hidden' ? 'Hidden until turned on.' : 'Shown by default.'}${t.isSample ? ' Sample content.' : ''}`, '');
  for (const c of t.categories) {
    out.push(`### ${c.name} (${c.sensitivity})`, '');
    if (c.description) out.push(c.description, '');
    for (const i of c.items) {
      const extra = [i.type === 'text' ? 'text' : '', i.sensitivity !== c.sensitivity ? i.sensitivity : ''].filter(Boolean).join(', ');
      out.push(`- ${i.label}${extra ? ` [${extra}]` : ''}${i.description ? `. ${i.description}` : ''}`);
    }
    out.push('');
  }
}

writeFileSync(new URL('../docs/TEMPLATE_WORDING.md', import.meta.url), `${out.join('\n').trimEnd()}\n`);
process.stdout.write(`Wrote docs/TEMPLATE_WORDING.md (${TEMPLATES.length} templates).\n`);
